const data=[['Luminance',-100,100,0,''],['Hue',-180,180,0,'°']];
const fmt=(v,s)=>v>0?`+${v}${s}`:`${v}${s}`;
function add(host, proposal, item){const [label,min,max,start,suffix]=item,row=document.createElement('div');row.className=`row ${label==='Hue'?'hue':''} ${proposal?'gooey':''}`;row.innerHTML=`<span class="label">${label}</span><output class="out">${fmt(start,suffix)}</output><div class="slot"><i class="track"></i>${proposal?'<div class="goo-layer"><i class="blob edge min"></i><i class="blob thumb"></i><i class="blob edge max"></i></div>':''}<input aria-label="${label}" type="range" min="${min}" max="${max}" value="${start}"></div>`;const input=row.querySelector('input'),out=row.querySelector('output'),thumb=row.querySelector('.thumb');const update=()=>{const p=(+input.value-min)/(max-min);out.textContent=fmt(+input.value,suffix);if(thumb)thumb.style.transform=`translateX(${p*(input.getBoundingClientRect().width-16)}px)`;row.classList.toggle('at-min',p===0);row.classList.toggle('at-max',p===1)};input.addEventListener('input',update);host.append(row);update();requestAnimationFrame(update)}
data.forEach(x=>add(document.querySelector('#normal'),false,x));data.forEach(x=>add(document.querySelector('#gooey'),true,x));document.querySelector('#theme').onclick=e=>{document.body.classList.toggle('light');e.target.textContent=document.body.classList.contains('light')?'Dark theme':'Light theme'};
